const input = $input.first().json;

/**
 * PostgreSQL normally returns JSONB as an object.
 * This also handles it safely if it arrives as text.
 */
let reviewData = input.review_data;

if (typeof reviewData === 'string') {
  try {
    reviewData = JSON.parse(reviewData);
  } catch {
    reviewData = {};
  }
}

/**
 * Escape text before inserting it into HTML.
 * This prevents client or AI content from becoming executable HTML.
 */
function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');
}

function displayText(value) {
  return escapeHtml(value).replaceAll('\n', '<br>');
}

function renderStringList(values) {
  if (!Array.isArray(values) || values.length === 0) {
    return '<p class="muted">None listed.</p>';
  }

  return `
    <ul>
      ${values
        .map((value) => `<li>${displayText(value)}</li>`)
        .join('')}
    </ul>
  `;
}

/**
 * Return an error page for invalid or expired links.
 */
if (!input.is_valid) {
  const statusCodes = {
    invalid_token: 404,
    already_decided: 409,
    expired: 410,
  };

  const html = `
    <!DOCTYPE html>
    <html lang="en">
      <head>
        <meta charset="UTF-8">
        <meta
          name="viewport"
          content="width=device-width, initial-scale=1.0"
        >

        <title>Campaign Review Unavailable</title>

        <style>
          * {
            box-sizing: border-box;
          }

          body {
            margin: 0;
            padding: 40px 20px;
            background: #f4f5f7;
            color: #202124;
            font-family:
              Inter,
              Arial,
              sans-serif;
          }

          .card {
            max-width: 680px;
            margin: 80px auto;
            padding: 36px;
            background: white;
            border: 1px solid #dadce0;
            border-radius: 16px;
            box-shadow:
              0 8px 28px rgba(0, 0, 0, 0.08);
          }

          h1 {
            margin-top: 0;
          }

          p {
            line-height: 1.6;
          }
        </style>
      </head>

      <body>
        <main class="card">
          <h1>Campaign review unavailable</h1>

          <p>
            ${escapeHtml(input.status_message)}
          </p>

          <p>
            Ask the campaign manager to generate a new review link.
          </p>
        </main>
      </body>
    </html>
  `;

  return [
    {
      json: {
        html,
        status_code:
          statusCodes[input.review_status] ?? 400,
      },
    },
  ];
}

const content = reviewData.content ?? {};

const foundation =
  content.strategic_foundation ?? {};

const angles =
  Array.isArray(content.ad_angles)
    ? content.ad_angles
    : [];

const hooks =
  Array.isArray(content.hooks)
    ? content.hooks
    : [];

const ads =
  Array.isArray(content.ads)
    ? content.ads
    : [];

const imagePrompts =
  Array.isArray(content.image_prompts)
    ? content.image_prompts
    : [];

const videos =
  Array.isArray(content.video_concepts)
    ? content.video_concepts
    : [];

const compliance =
  content.compliance_review ?? {};

/**
 * This will be handled by a separate POST Webhook workflow.
 */
const decisionUrl =
 'http://localhost:5678/webhook/adflow-approval-decision';

const html = `
<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8">

    <meta
      name="viewport"
      content="width=device-width, initial-scale=1.0"
    >

    <title>
      ${escapeHtml(reviewData.campaign_code)} Campaign Review
    </title>

    <style>
      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        background: #f4f5f7;
        color: #202124;
        font-family:
          Inter,
          Arial,
          sans-serif;
        line-height: 1.6;
      }

      .page {
        width: min(1080px, calc(100% - 32px));
        margin: 32px auto 80px;
      }

      .header,
      .section,
      .decision-panel {
        background: white;
        border: 1px solid #dadce0;
        border-radius: 14px;
        box-shadow:
          0 4px 18px rgba(0, 0, 0, 0.05);
      }

      .header {
        padding: 32px;
        margin-bottom: 22px;
      }

      .section {
        padding: 28px;
        margin-bottom: 22px;
      }

      .decision-panel {
        padding: 28px;
        border: 2px solid #202124;
      }

      h1,
      h2,
      h3,
      p {
        margin-top: 0;
      }

      h1 {
        margin-bottom: 8px;
        font-size: 30px;
      }

      h2 {
        margin-bottom: 18px;
        font-size: 22px;
      }

      h3 {
        margin-bottom: 8px;
      }

      .meta-grid,
      .grid {
        display: grid;
        gap: 16px;
      }

      .meta-grid {
        grid-template-columns:
          repeat(auto-fit, minmax(210px, 1fr));
        margin-top: 24px;
      }

      .grid {
        grid-template-columns:
          repeat(auto-fit, minmax(280px, 1fr));
      }

      .meta,
      .item {
        padding: 18px;
        background: #f8f9fa;
        border: 1px solid #e3e5e8;
        border-radius: 10px;
      }

      .label {
        display: block;
        margin-bottom: 4px;
        color: #5f6368;
        font-size: 12px;
        font-weight: 700;
        letter-spacing: 0.05em;
        text-transform: uppercase;
      }

      .muted {
        color: #5f6368;
      }

      ul,
      ol {
        padding-left: 24px;
      }

      .ad-copy {
        white-space: pre-wrap;
      }

      form {
        display: grid;
        gap: 18px;
      }

      label {
        font-weight: 700;
      }

      input,
      textarea {
        width: 100%;
        margin-top: 7px;
        padding: 12px;
        background: white;
        border: 1px solid #bdc1c6;
        border-radius: 8px;
        color: #202124;
        font: inherit;
      }

      textarea {
        min-height: 130px;
        resize: vertical;
      }

      .choices {
        display: grid;
        gap: 10px;
      }

      .choice {
        display: flex;
        gap: 10px;
        align-items: flex-start;
        padding: 14px;
        border: 1px solid #dadce0;
        border-radius: 8px;
      }

      .choice input {
        width: auto;
        margin-top: 5px;
      }

      button {
        padding: 14px 20px;
        border: 0;
        border-radius: 8px;
        background: #202124;
        color: white;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
      }

      button:hover {
        opacity: 0.9;
      }

      @media (max-width: 640px) {
        .page {
          width: min(100% - 20px, 1080px);
          margin-top: 10px;
        }

        .header,
        .section,
        .decision-panel {
          padding: 20px;
        }
      }
    </style>
  </head>

  <body>
    <main class="page">
      <section class="header">
        <span class="label">Campaign review</span>

        <h1>
          ${escapeHtml(reviewData.company_name)}
        </h1>

        <p class="muted">
          Review the AI-generated campaign before it moves
          into creative production.
        </p>

        <div class="meta-grid">
          <div class="meta">
            <span class="label">Campaign reference</span>
            ${escapeHtml(reviewData.campaign_code)}
          </div>

          <div class="meta">
            <span class="label">Version</span>
            ${escapeHtml(reviewData.version_number)}
          </div>

          <div class="meta">
            <span class="label">Objective</span>
            ${escapeHtml(reviewData.objective)}
          </div>

          <div class="meta">
            <span class="label">Brand tone</span>
            ${escapeHtml(reviewData.brand_tone)}
          </div>

          <div class="meta">
            <span class="label">AI model</span>
            ${escapeHtml(reviewData.model_name)}
          </div>

          <div class="meta">
            <span class="label">Link expires</span>
            ${escapeHtml(reviewData.expires_at)}
          </div>
        </div>
      </section>

      <section class="section">
        <h2>Client brief</h2>

        <div class="grid">
          <div class="item">
            <span class="label">Product or service</span>
            ${displayText(reviewData.product_service)}
          </div>

          <div class="item">
            <span class="label">Target audience</span>
            ${displayText(reviewData.target_audience)}
          </div>

          <div class="item">
            <span class="label">Offer</span>
            ${displayText(reviewData.offer)}
          </div>

          <div class="item">
            <span class="label">Website</span>
            ${displayText(reviewData.website || 'Not provided')}
          </div>
        </div>
      </section>

      <section class="section">
        <h2>Campaign summary</h2>

        <p>
          ${displayText(content.campaign_summary)}
        </p>
      </section>

      <section class="section">
        <h2>Strategic foundation</h2>

        <div class="grid">
          <div class="item">
            <span class="label">Audience summary</span>
            ${displayText(foundation.audience_summary)}
          </div>

          <div class="item">
            <span class="label">Primary problem</span>
            ${displayText(foundation.primary_problem)}
          </div>

          <div class="item">
            <span class="label">Desired outcome</span>
            ${displayText(foundation.desired_outcome)}
          </div>

          <div class="item">
            <span class="label">Offer positioning</span>
            ${displayText(foundation.offer_positioning)}
          </div>
        </div>
      </section>

      <section class="section">
        <h2>Advertising angles</h2>

        <div class="grid">
          ${angles
            .map(
              (angle) => `
                <article class="item">
                  <span class="label">
                    ${escapeHtml(angle.angle_id)}
                  </span>

                  <h3>${escapeHtml(angle.name)}</h3>

                  <p>
                    <strong>Core message:</strong><br>
                    ${displayText(angle.core_message)}
                  </p>

                  <p>
                    <strong>Why it may work:</strong><br>
                    ${displayText(angle.rationale)}
                  </p>

                  <p class="muted">
                    Awareness stage:
                    ${escapeHtml(angle.awareness_stage)}
                  </p>
                </article>
              `
            )
            .join('')}
        </div>
      </section>

      <section class="section">
        <h2>Hooks</h2>

        <ol>
          ${hooks
            .map(
              (hook) => `
                <li>
                  <strong>
                    ${escapeHtml(hook.hook_id)}
                  </strong>
                  —
                  ${displayText(hook.hook_text)}
                  <span class="muted">
                    (${escapeHtml(hook.angle_id)})
                  </span>
                </li>
              `
            )
            .join('')}
        </ol>
      </section>

      <section class="section">
        <h2>Ad copy</h2>

        <div class="grid">
          ${ads
            .map(
              (ad) => `
                <article class="item">
                  <span class="label">
                    ${escapeHtml(ad.ad_id)}
                    ·
                    ${escapeHtml(ad.angle_id)}
                  </span>

                  <h3>
                    ${escapeHtml(ad.headline)}
                  </h3>

                  <p class="ad-copy">
                    ${displayText(ad.primary_text)}
                  </p>

                  <p>
                    <strong>Description:</strong><br>
                    ${displayText(ad.description)}
                  </p>

                  <p>
                    <strong>Call to action:</strong><br>
                    ${displayText(ad.call_to_action)}
                  </p>
                </article>
              `
            )
            .join('')}
        </div>
      </section>

      <section class="section">
        <h2>AI image prompts</h2>

        <div class="grid">
          ${imagePrompts
            .map(
              (image) => `
                <article class="item">
                  <span class="label">
                    ${escapeHtml(image.prompt_id)}
                    ·
                    ${escapeHtml(image.angle_id)}
                  </span>

                  <h3>
                    ${escapeHtml(image.concept_name)}
                  </h3>

                  <p>
                    ${displayText(image.prompt)}
                  </p>

                  <p>
                    <strong>Suggested overlay:</strong><br>
                    ${displayText(image.overlay_text)}
                  </p>
                </article>
              `
            )
            .join('')}
        </div>
      </section>

      <section class="section">
        <h2>Video concepts</h2>

        <div class="grid">
          ${videos
            .map(
              (video) => `
                <article class="item">
                  <span class="label">
                    ${escapeHtml(video.concept_id)}
                    ·
                    ${escapeHtml(video.duration_seconds)} seconds
                  </span>

                  <h3>
                    ${escapeHtml(video.concept_name)}
                  </h3>

                  <p>
                    <strong>Opening hook:</strong><br>
                    ${displayText(video.opening_hook)}
                  </p>

                  <p><strong>Scene plan:</strong></p>

                  ${renderStringList(video.scene_plan)}

                  <p>
                    <strong>Voiceover:</strong><br>
                    ${displayText(video.voiceover)}
                  </p>

                  <p>
                    <strong>End card:</strong><br>
                    ${displayText(video.end_card_text)}
                  </p>
                </article>
              `
            )
            .join('')}
        </div>
      </section>

      <section class="section">
        <h2>Compliance and quality review</h2>

        <h3>Unsupported claims to avoid</h3>
        ${renderStringList(compliance.unsupported_claims)}

        <h3>Possible policy or sensitivity risks</h3>
        ${renderStringList(
          compliance.sensitive_or_policy_risks
        )}

        <h3>Items requiring human confirmation</h3>
        ${renderStringList(
          compliance.notes_for_human_reviewer
        )}
      </section>

      <section class="decision-panel">
        <h2>Submit your review</h2>

        <p class="muted">
          Nothing will be published automatically.
          Your decision will update the campaign workflow.
        </p>

        <form
          method="POST"
          action="${decisionUrl}"
        >
          <input
            type="hidden"
            name="token"
            value="${escapeHtml(reviewData.decision_token)}"
          >

          <label>
            Reviewer name

            <input
              type="text"
              name="reviewer_name"
              maxlength="150"
              required
            >
          </label>

          <label>
            Reviewer email

            <input
              type="email"
              name="reviewer_email"
              maxlength="255"
              required
            >
          </label>

          <div>
            <p><strong>Decision</strong></p>

            <div class="choices">
              <label class="choice">
                <input
                  type="radio"
                  name="decision"
                  value="approved"
                  required
                >

                <span>
                  <strong>Approve</strong><br>
                  The campaign can move to production.
                </span>
              </label>

              <label class="choice">
                <input
                  type="radio"
                  name="decision"
                  value="revision_requested"
                  required
                >

                <span>
                  <strong>Request revision</strong><br>
                  Generate another version using my feedback.
                </span>
              </label>

              <label class="choice">
                <input
                  type="radio"
                  name="decision"
                  value="rejected"
                  required
                >

                <span>
                  <strong>Reject</strong><br>
                  Stop this campaign package.
                </span>
              </label>
            </div>
          </div>

          <label>
            Feedback or revision instructions

            <textarea
              name="feedback"
              maxlength="5000"
              placeholder="Explain requested changes, concerns, or approval notes."
            ></textarea>
          </label>

          <button type="submit">
            Submit campaign decision
          </button>
        </form>
      </section>
    </main>
  </body>
</html>
`;

return [
  {
    json: {
      html,
      status_code: 200,
    },
  },
];
